<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver;

use Psr\Container\ContainerInterface;

use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver\Rest\TemplateAssetAllowController;
use Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver\Rest\TemplateAssetListController;
use Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver\Rest\TemplateAssetCreateController;
use Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver\Rest\TemplateAssetRetrieveController;
use Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver\Rest\TemplateAssetUpdateController;
use Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver\Rest\TemplateAssetDeleteController;
use Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver\Rest\TemplateAssetEnableController;
use Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver\Rest\TemplateAssetDisableController;
use Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driver\Rest\TemplateAssetTempContentUploadController;

use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Service\Visibility\TemplateAssetRestrictFilterToVisibility;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Fields\FixTenantExcludingRoot;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Service\Visibility\TemplateAssetCollectNonEditableFields;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Allow\Create\IsAuthenticatedCreateAllow;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Create\TemplateAssetCreateAllowDecision;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Allow\Update\IsAuthenticatedUpdateAllow;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Update\TemplateAssetUpdateAllowDecision;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Allow\Retrieve\IsAuthenticatedRetrieveAllow;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Retrieve\TemplateAssetRetrieveAllowDecision;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Allow\List\IsAuthenticatedListAllow;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\List\TemplateAssetListAllowDecision;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Allow\Delete\IsAuthenticatedDeleteAllow;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Delete\TemplateAssetDeleteAllowDecision;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Allow\Enable\IsAuthenticatedEnableAllow;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Enable\TemplateAssetEnableAllowDecision;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Allow\Disable\IsAuthenticatedDisableAllow;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Disable\TemplateAssetDisableAllowDecision;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Policy\Allow\UploadContent\IsAuthenticatedUploadContentAllow;
use Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\UploadContent\TemplateAssetUploadContentAllowDecision;
use Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driven\TemplateAssetReadRepositoryAdapter;
use Civi\Lughauth\Features\Document\TemplateAsset\Infrastructure\Driven\TemplateAssetWriteRepositoryAdapter;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetReadGateway;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Gateway\TemplateAssetWriteGateway;

class TemplateAssetPlugin extends MicroPlugin
{
  #[Override]
  public function registerServiceDefinition(array $def): array
  {
    $def[TemplateAssetReadGateway::class] = \DI\autowire( TemplateAssetReadRepositoryAdapter::class);
    $def[TemplateAssetWriteGateway::class] = \DI\autowire( TemplateAssetWriteRepositoryAdapter::class);
    return $def;
  }
  #[Override]
  public function registerRoutes(RouteCollectorProxy $collector): void
  {
    $collector->group('/api/document/template-asset', [$this, 'setRoutesForTemplateAsset']);
    $collector->group('/api/me/acl/document/template-asset', [$this, 'setRoutesForTemplateAssetAcl']);
  }
  #[Override]
  public function registerEvents(EventListenersRegistrarInterface $listener): void
  {
    $listener->registerListener(TemplateAssetRestrictFilterToVisibility::class, TenantAccesible::class);
    $listener->registerListener(TemplateAssetCollectNonEditableFields::class, FixTenantExcludingRoot::class);
$listener->registerListener(TemplateAssetCreateAllowDecision::class, IsAuthenticatedCreateAllow::class);
$listener->registerListener(TemplateAssetUpdateAllowDecision::class, IsAuthenticatedUpdateAllow::class);
$listener->registerListener(TemplateAssetRetrieveAllowDecision::class, IsAuthenticatedRetrieveAllow::class);
$listener->registerListener(TemplateAssetListAllowDecision::class, IsAuthenticatedListAllow::class);
$listener->registerListener(TemplateAssetDeleteAllowDecision::class, IsAuthenticatedDeleteAllow::class);
$listener->registerListener(TemplateAssetEnableAllowDecision::class, IsAuthenticatedEnableAllow::class);
$listener->registerListener(TemplateAssetDisableAllowDecision::class, IsAuthenticatedDisableAllow::class);
$listener->registerListener(TemplateAssetUploadContentAllowDecision::class, IsAuthenticatedUploadContentAllow::class);
  }
  #[Override]
  public function registerStartup(StartupProcessor $processor): void
  {
$processor->register(function (ContainerInterface $container) {
    $handler = $container->get(Handler::class);
    $handler->registerResourceAction("template-asset", "list", "READ");
    $handler->registerResourceAction("template-asset", "create", "WRITE");
    $handler->registerResourceAction("template-asset", "retrieve", "READ");
    $handler->registerResourceAction("template-asset", "update", "WRITE");
    $handler->registerResourceAction("template-asset", "delete", "WRITE");
    $handler->registerResourceAction("template-asset", "enable", "WRITE");
    $handler->registerResourceAction("template-asset", "disable", "WRITE");

    $handler->registerResourceAttribute("template-asset", "tenant", "MANAGE");
    $handler->registerResourceAttribute("template-asset", "code", "MANAGE");
    $handler->registerResourceAttribute("template-asset", "type", "MANAGE");
    $handler->registerResourceAttribute("template-asset", "content", "MANAGE");
    $handler->registerResourceAttribute("template-asset", "enabled", "MANAGE");
    $handler->registerResourceAttribute("template-asset", "version", "MANAGE");
}, StartupProcessor::before( SecurityPlugin::STARTUP_ORDER) );  }
  public function setRoutesForTemplateAssetAcl(RouteCollectorProxy $templateAssetGroup): void
  {
    $templateAssetGroup->get('', [TemplateAssetAllowController::class, 'genericAllow']);
    $templateAssetGroup->get('/{uid}', [TemplateAssetAllowController::class, 'contextualAllow']);
  }
  public function setRoutesForTemplateAsset(RouteCollectorProxy $templateAssetGroup): void
  {
    $templateAssetGroup->get('', [TemplateAssetListController::class, 'list']);
    $templateAssetGroup->post('', [TemplateAssetCreateController::class, 'create']);
    $templateAssetGroup->get('/{uid}', [TemplateAssetRetrieveController::class, 'retrieve']);
    $templateAssetGroup->get('/{uid}/content', [TemplateAssetRetrieveController::class, 'retrieveContent']);
    $templateAssetGroup->put('/{uid}', [TemplateAssetUpdateController::class, 'update']);
    $templateAssetGroup->delete('/{uid}', [TemplateAssetDeleteController::class, 'delete']);
    $templateAssetGroup->delete('', [TemplateAssetDeleteController::class, 'deleteAllForQuery']);
    $templateAssetGroup->get('/~/delete-status/{uid}', [TemplateAssetDeleteController::class, 'checkDeleteAllForQueryStatus']);
    $templateAssetGroup->patch('/~/enable', [TemplateAssetEnableController::class, 'enableAllForQuery']);
    $templateAssetGroup->patch('/{uid}/enable', [TemplateAssetEnableController::class, 'enable']);
    $templateAssetGroup->get('/~/enable-status/{uid}', [TemplateAssetEnableController::class, 'checkEnableAllForQueryStatus']);
    $templateAssetGroup->patch('/~/disable', [TemplateAssetDisableController::class, 'disableAllForQuery']);
    $templateAssetGroup->patch('/{uid}/disable', [TemplateAssetDisableController::class, 'disable']);
    $templateAssetGroup->get('/~/disable-status/{uid}', [TemplateAssetDisableController::class, 'checkDisableAllForQueryStatus']);
    $templateAssetGroup->post('/-/temp-content', [TemplateAssetTempContentUploadController::class, 'uploadTemp']);
    $templateAssetGroup->get('/-/temp-content', [TemplateAssetTempContentUploadController::class, 'getTemp']);
  }
}
